import sys
input = sys.stdin.read().split()

T = int(input[0])
index = 1
results = []

for _ in range(T):
    N = int(input[index])
    K = int(input[index + 1])
    index += 2

    if K > N:
        results.append(-1)
        continue

    perm = list(range(1, N + 1))
    good_indices = set()

    for i in range(1, N + 1):
        if len(good_indices) == K:
            break
        if perm[i - 1] % i == 0:
            good_indices.add(i - 1)
        else:
            for j in range(i, N + 1):
                if j % i == 0 and j not in perm[:i - 1]:
                    perm[i - 1], perm[j - 1] = perm[j - 1], perm[i - 1]
                    good_indices.add(i - 1)
                    break

    if len(good_indices) != K:
        results.append(-1)
    else:
        results.append(' '.join(map(str, perm)))

for result in results:
    print(result)
